// Guard invoked by lint-staged (see the "lint-staged" field in package.json)
// whenever a root build artifact is staged.
//
// dubplus.js / dubplus.min.js / dubplus.css are generated by `vite build` and
// are rebuilt + committed automatically by CI (.github/workflows/build.yml)
// when a PR is merged. Committing them on a feature branch only produces noisy
// merge conflicts with those auto-commits, so we block it here.
//
// lint-staged passes the matched staged file paths (absolute) as CLI arguments;
// we relativize them to the repo root so the printed command is copy-pasteable.

import { relative } from 'node:path';

const files = process.argv
  .slice(2)
  .map((file) => relative(process.cwd(), file));

console.error(
  [
    '',
    '✖ Refusing to commit generated build files:',
    ...files.map((file) => `    ${file}`),
    '',
    'CI rebuilds these on merge, so they should never be committed on a branch.',
    'Unstage them and commit again:',
    '',
    `    git restore --staged ${files.join(' ')}`,
    '',
  ].join('\n'),
);

process.exit(1);
